func (e *Engine) getOrCompile(path string) (*goja.Program, error) {
	e.mu.RLock()
	prog, exists := e.programs[path]
	e.mu.RUnlock()
	if exists {
		return prog, nil
	}

	e.mu.Lock()
	defer e.mu.Unlock()

	if prog, exists := e.programs[path]; exists {
		return prog, nil
	}

	code, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	prog, err = goja.Compile(filepath.Base(path), string(code), true)
	if err != nil {
		return nil, err
	}

	e.programs[path] = prog
	return prog, nil
}

